#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=13

# ── Wizard-local settings and helpers ─────────────────────────────────────

REPO_ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || {
  echo "Ejecuta este asistente dentro del repositorio de Quitsie." >&2
  exit 1
}
cd "$REPO_ROOT"

# Non-secret answers (domain, GCP project, public keys) are remembered here so
# a re-run picks up where it stopped. The file is git-ignored (*.env). Secrets
# are never written to disk: they go straight to GitHub, or are typed on the VM.
ENV_FILE="$REPO_ROOT/.quitsie-wizard.env"

VM_NAME=quitsie
GCP_ZONE="${QUITSIE_ZONE:-us-east1-b}"            # us-east1 is a free-tier region
IMAGE_FAMILY="${QUITSIE_IMAGE_FAMILY:-debian-13}" # debian-12 also works
QUITSIE_DOMAIN=""
GCP_PROJECT=""
_SECRET_INPUT=""

have_cmd() { command -v "$1" >/dev/null 2>&1; }

# run CMD... shows the command, runs it, and reports a failure without ending the wizard.
run() {
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  "$@" && return 0
  warn "falló: $*"
  return 1
}

secret_exists() { gh secret list --json name --jq '.[].name' 2>/dev/null | grep -qx "$1"; }

# capture_secret NAME "Prompt" asks with hidden input and sets the GitHub secret
# NAME. Nothing is written to disk. Keeps an existing secret unless told otherwise.
capture_secret() {
  local name="$1" prompt="$2"
  if secret_exists "$name" && ! confirm "El secreto $name ya existe en GitHub. ¿Reemplazarlo?"; then
    note "se conserva $name"
    return 0
  fi
  ask_secret _SECRET_INPUT "$prompt"
  if [[ -z "$_SECRET_INPUT" ]]; then
    SKIPPED+=("GitHub secret $name (vacío; ejecuta: gh secret set $name)")
    warn "valor vacío: no se guardó $name"
    return 0
  fi
  set_secret "$name" "$_SECRET_INPUT"
  _SECRET_INPUT=""
}

# http_status URL prints the HTTP status ("000" when nothing answers).
http_status() { curl -s -o /dev/null -m 15 -w '%{http_code}' "$1" 2>/dev/null || true; }

# vm_ssh [gcloud compute ssh args] reaches the VM through Google's IAP, so port 22 is never public.
vm_ssh() { gcloud compute ssh "$VM_NAME" --zone "$GCP_ZONE" --tunnel-through-iap "$@"; }

banner "Quitsie: primer despliegue"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Herramientas en tu ordenador"
say "Este asistente te lleva paso a paso. Los secretos van directo a GitHub o los"
say "escribes en la VM; ni se guardan en disco ni los compartes con nadie más."
printf '\n'

until have_cmd gh && gh auth status >/dev/null 2>&1; do
  warn "GitHub CLI no está listo."
  step "Instálalo con: brew install gh"
  step "Entra con: gh auth login"
  pause "Cuando esté listo, pulsa Enter"
done
GH_REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null || true)
if [[ -z "$GH_REPO" ]]; then
  warn "gh no reconoce el repositorio de este directorio. ¿Existe el remoto origin y tienes acceso?"
  exit 1
fi
say "Repositorio de GitHub: $GH_REPO"

for tool in git ssh-keygen curl tar; do
  have_cmd "$tool" || { warn "falta $tool"; exit 1; }
done
if ! have_cmd gcloud; then
  warn "Falta gcloud (Google Cloud CLI)."
  step "Instálalo con: brew install --cask gcloud-cli   (o https://cloud.google.com/sdk/docs/install)"
  step "Abre una terminal nueva y vuelve a ejecutar este asistente: recuerda lo ya guardado."
  exit 1
fi
say "Herramientas listas (gh, gcloud, git, ssh-keygen, curl, tar)."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Dominio: quitsie.com y quitsie.app"
say "Se compran en Cloudflare Registrar, a precio de mayorista y con el DNS ya en Cloudflare."
open_url "https://dash.cloudflare.com/sign-up"
step "Crea tu cuenta de Cloudflare (o entra) y verifica tu email."
step "Menú lateral → Domain Registration → Register Domains."
step "Busca quitsie.com, cómpralo y deja activa la renovación automática."
step "Repite con quitsie.app. Si Cloudflare no lo ofrece, cómpralo en otro registrador y cambia sus nameservers a los de Cloudflare (Websites → Add a domain)."
note "El pago lo haces tú en la página de Cloudflare."
pause "Cuando tengas el dominio principal, pulsa Enter"
while true; do
  ask QUITSIE_DOMAIN "Dominio principal (Enter para quitsie.com):"
  QUITSIE_DOMAIN="${QUITSIE_DOMAIN:-quitsie.com}"
  [[ "$QUITSIE_DOMAIN" =~ ^([a-z0-9-]+\.)+[a-z]{2,}$ ]] && break
  warn "Escríbelo en minúsculas y sin https://, por ejemplo quitsie.com"
done
write_env QUITSIE_DOMAIN "$QUITSIE_DOMAIN"
if have_cmd dig; then
  ns=$(dig +short NS "$QUITSIE_DOMAIN" 2>/dev/null | tr '\n' ' ')
  case "$ns" in
    *cloudflare*) say "Los nameservers de $QUITSIE_DOMAIN son de Cloudflare: bien." ;;
    *) warn "Aún no veo nameservers de Cloudflare para $QUITSIE_DOMAIN (${ns:-sin respuesta}). Puede tardar; sigue y lo comprobarás con el túnel." ;;
  esac
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare R2: el bucket de respaldos"
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "Si R2 aún no está activado, actívalo. El plan gratuito incluye 10 GB; puede pedirte un método de pago, pero no cobra dentro del límite."
step "Create bucket. Nombre exacto: quitsie-backups  (deploy/litestream.yml usa ese nombre)."
step "Location: Automatic. Storage class: Standard. No actives el acceso público."
step "Anota el Account ID (R2 → Overview → Account Details): la VM te lo pedirá más adelante."
pause "Cuando el bucket exista, pulsa Enter"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: proyecto, facturación y presupuesto"
open_url "https://console.cloud.google.com/projectcreate"
step "Entra con tu cuenta de Google y crea un proyecto llamado quitsie."
step "Vincúlalo a una cuenta de facturación (hace falta una tarjeta, incluso para la capa gratuita)."
warn "La VM e2-micro es gratis, pero su IP pública NO: Google cobra 0,005 USD por hora (unos 3,65 USD al mes) por cada IPv4 externa."
open_url "https://console.cloud.google.com/billing/budgets"
step "Billing → Budgets & alerts → Create budget: 5 USD al mes, con alertas al 50 % y al 100 %. Así cualquier cargo inesperado te avisa."
pause "Cuando el proyecto y el presupuesto estén listos, pulsa Enter"
while true; do
  ask GCP_PROJECT "ID del proyecto (no el nombre; sale en la página del proyecto):"
  [[ "$GCP_PROJECT" =~ ^[a-z][a-z0-9-]{4,28}[a-z0-9]$ ]] && break
  warn "Un ID de proyecto tiene entre 6 y 30 caracteres: minúsculas, números y guiones."
done
write_env GCP_PROJECT "$GCP_PROJECT"
export CLOUDSDK_CORE_PROJECT="$GCP_PROJECT"

if ! gcloud auth list --filter=status:ACTIVE --format='value(account)' 2>/dev/null | grep -q .; then
  step "En esta misma terminal o en otra, ejecuta: gcloud auth login"
  pause "Cuando hayas entrado, pulsa Enter"
fi
if confirm "¿Activar las APIs de Compute Engine e IAP en $GCP_PROJECT?"; then
  run gcloud services enable compute.googleapis.com iap.googleapis.com \
    || SKIPPED+=("APIs de Google (gcloud services enable compute.googleapis.com iap.googleapis.com)")
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: la VM y su cortafuegos"
say "VM $VM_NAME: e2-micro en $GCP_ZONE, imagen $IMAGE_FAMILY, disco estándar de 30 GB."
note "Es la combinación de la capa gratuita: tipo e2-micro, región us-east1, disco pd-standard (el predeterminado, pd-balanced, SÍ se cobra)."
note "Sin cuenta de servicio: la VM no necesita llamar a ninguna API de Google."
warn "Se crea con IP pública efímera (necesita salida a Internet): unos 3,65 USD al mes. No se abre ningún puerto de entrada."
if gcloud compute instances describe "$VM_NAME" --zone "$GCP_ZONE" >/dev/null 2>&1; then
  say "La VM $VM_NAME ya existe: no la toco."
elif confirm "¿Crear la VM ahora?"; then
  run gcloud compute instances create "$VM_NAME" --zone "$GCP_ZONE" \
    --machine-type e2-micro --image-family "$IMAGE_FAMILY" --image-project debian-cloud \
    --boot-disk-size 30GB --boot-disk-type pd-standard \
    --no-service-account --no-scopes --tags quitsie \
    || { SKIPPED+=("Crear la VM (si falla la imagen, vuelve a ejecutar con QUITSIE_IMAGE_FAMILY=debian-12)"); }
fi

say "Cortafuegos: solo el rango de IAP (Google) puede llegar al puerto 22, y solo para tu administración."
if ! gcloud compute firewall-rules describe allow-iap-ssh >/dev/null 2>&1; then
  run gcloud compute firewall-rules create allow-iap-ssh --network default --direction INGRESS \
    --action ALLOW --rules tcp:22 --source-ranges 35.235.240.0/20 --target-tags quitsie \
    || SKIPPED+=("Regla de cortafuegos allow-iap-ssh")
fi
for rule in default-allow-ssh default-allow-rdp default-allow-icmp; do
  if gcloud compute firewall-rules describe "$rule" >/dev/null 2>&1; then
    if confirm "La regla $rule deja la VM abierta a Internet. ¿Borrarla?"; then
      run gcloud compute firewall-rules delete "$rule" --quiet || true
    else
      SKIPPED+=("Borrar la regla de cortafuegos $rule")
    fi
  fi
done

say "Compruebo el acceso por IAP (la primera vez gcloud crea tu clave SSH y puede pedirte una frase)."
if ! run vm_ssh --command 'echo "VM lista: $(hostname)"' </dev/null; then
  warn "No entré. Si dice permission denied, dale a tu cuenta el rol «IAP-secured Tunnel User» en IAM; si dice timeout, espera un minuto a que arranque la VM."
  pause "Cuando lo hayas resuelto, pulsa Enter (el asistente lo reintentará en la etapa 9)"
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare Tunnel: la única puerta de entrada"
open_url "https://one.dash.cloudflare.com/"
step "Primera vez en Zero Trust: elige un nombre de equipo (p. ej. quitsie) y el plan Free (puede pedir un método de pago; el plan no cuesta nada)."
step "Dashboard de Cloudflare → Networking → Tunnels (en Zero Trust: Networks → Tunnels) → Create a tunnel → Cloudflared."
step "Nombre: quitsie. En «Install and run connectors» elige Debian y 64-bit."
warn "NO ejecutes el comando que muestra: provision.sh instala el servicio en la VM. Solo contiene tu token; lo pegarás allí (etapa 9)."
step "Pestaña Routes → Add route → Published application: subdominio vacío, dominio $QUITSIE_DOMAIN, servicio HTTP y URL localhost:8080."
note "Aún no publiques ssh.$QUITSIE_DOMAIN: va en la etapa 11, protegido por Access."
note "Si ya hay un registro DNS para $QUITSIE_DOMAIN, bórralo antes: el túnel crea el suyo."
pause "Cuando la ruta de la aplicación esté guardada, pulsa Enter"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Clave SSH solo para desplegar"
say "Genero un par de claves para que GitHub Actions despliegue. La privada va directa al"
say "secreto DEPLOY_SSH_KEY y no queda en tu disco; la pública se instala en la VM, donde"
say "esa clave solo puede ejecutar quitsie-deploy (ni shell, ni túneles)."
if [[ -n "$(_existing DEPLOY_PUBKEY || true)" ]] && secret_exists DEPLOY_SSH_KEY \
  && ! confirm "Ya hay una clave de despliegue. ¿Generar una nueva (hay que volver a aprovisionar la VM)?"; then
  note "se conserva la clave de despliegue"
else
  keydir=$(mktemp -d)
  ssh-keygen -q -t ed25519 -N '' -C quitsie-deploy -f "$keydir/key"
  set_secret DEPLOY_SSH_KEY "$(cat "$keydir/key")"
  if secret_exists DEPLOY_SSH_KEY; then
    write_env DEPLOY_PUBKEY "$(cut -d' ' -f1,2 "$keydir/key.pub") quitsie-deploy"
  else
    warn "No pude guardar DEPLOY_SSH_KEY en GitHub; descarto la clave. Revisa gh auth status y repite esta etapa."
  fi
  rm -rf -- "${keydir:?}"
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare R2: token de API para Litestream"
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "R2 → Overview → API Tokens → Manage → Create Account API token."
step "Nombre: quitsie-litestream. Permisos: Object Read & Write."
step "Specify bucket(s): solo quitsie-backups. Create."
step "Verás un Access Key ID y un Secret Access Key. Copia el Account ID también."
warn "No los pegues aquí ni en ningún chat: en la etapa 9 los escribes en la VM. El Secret Access Key se muestra una sola vez, así que no cierres esa pestaña."
pause "Cuando tengas el token a la vista, pulsa Enter"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Aprovisionar la VM"
say "Copio los archivos versionados de deploy/ a la VM y ejecuto provision.sh allí."
say "Te pedirá, con entrada oculta, el Account ID y las claves de R2 y el token del túnel;"
say "se escriben en /etc/quitsie/*.env (modo 600) y en ningún otro sitio. Puedes pegar el comando completo del túnel."
DEPLOY_PUBKEY=$(_existing DEPLOY_PUBKEY || true)
if [[ -z "$DEPLOY_PUBKEY" ]]; then
  warn "No hay clave pública de despliegue (etapa 7). Repite esa etapa antes de seguir."
  exit 1
fi
if confirm "¿Copiar deploy/ y ejecutar provision.sh en la VM?"; then
  export COPYFILE_DISABLE=1 # keeps macOS from adding ._* files to the archive
  if git ls-files -z deploy | xargs -0 tar -cf - \
    | vm_ssh --command 'rm -rf ~/quitsie-deploy && mkdir ~/quitsie-deploy && tar -xf - -C ~/quitsie-deploy --strip-components=1'; then
    run vm_ssh --command "sudo env QUITSIE_DEPLOY_PUBKEY='$DEPLOY_PUBKEY' bash ~/quitsie-deploy/provision.sh" -- -t \
      || SKIPPED+=("provision.sh falló: corrige el error y vuelve a ejecutar este asistente")
  else
    warn "No pude copiar deploy/ a la VM."
    SKIPPED+=("Copiar deploy/ a la VM y ejecutar provision.sh (docs/despliegue.md)")
  fi
fi

host_key=$(vm_ssh --command "awk '{print \$1, \$2}' /etc/ssh/ssh_host_ed25519_key.pub" </dev/null 2>/dev/null | tail -n1 | tr -d '\r' || true)
if [[ ! "$host_key" =~ ^ssh-ed25519\ [A-Za-z0-9+/]+=*$ ]]; then
  say "No pude leer la clave pública de la VM sola. provision.sh la imprimió al final (empieza por ssh-ed25519)."
  ask DEPLOY_SSH_HOST_KEY "Pégala aquí (es pública):"
  host_key="$DEPLOY_SSH_HOST_KEY"
fi
write_env DEPLOY_SSH_HOST_KEY "$host_key"

status=$(http_status "https://$QUITSIE_DOMAIN/api/v1/health")
case "$status" in
  200 | 502 | 503) say "El túnel responde ($status). Un 502 es lo esperado: todavía no hay binario desplegado." ;;
  530) warn "Cloudflare dice 530: el túnel no está conectado. Mira el estado del túnel en el panel y 'journalctl -u cloudflared' en la VM." ;;
  *) warn "https://$QUITSIE_DOMAIN respondió $status. Si el dominio es nuevo, el DNS puede tardar unos minutos." ;;
esac
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Cloudflare Access: token de servicio para GitHub Actions"
open_url "https://one.dash.cloudflare.com/"
step "Access controls → Service credentials → Service Tokens → Create Service Token."
step "Nombre: github-actions-deploy. Duración: la más larga que ofrezca."
warn "El token caduca: apunta la fecha en tu calendario. Ese día el despliegue fallará con un error de Access; se arregla creando otro y repitiendo esta etapa."
step "Generate token. Copia el Client ID y el Client Secret (el secreto se muestra una sola vez)."
capture_secret CF_ACCESS_CLIENT_ID "Client ID:"
capture_secret CF_ACCESS_CLIENT_SECRET "Client Secret:"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Proteger y publicar ssh.$QUITSIE_DOMAIN"
warn "El orden importa: primero la aplicación de Access, después la ruta. Así el SSH nunca queda en Internet sin protección."
open_url "https://one.dash.cloudflare.com/"
say "A) La aplicación de Access"
step "Access controls → Applications → Add an application → Self-hosted."
step "Nombre: quitsie-ssh. Public hostname: ssh.$QUITSIE_DOMAIN (subdominio ssh, dominio $QUITSIE_DOMAIN)."
step "Política: nombre github-actions, acción Service Auth, regla Include → Service Token → github-actions-deploy."
step "No añadas políticas Allow para personas: tu acceso de emergencia es gcloud con IAP."
step "Guarda la aplicación."
pause "Cuando la aplicación esté guardada, pulsa Enter"
say "B) La ruta del túnel"
step "Networking → Tunnels → quitsie → Routes → Add route → Published application."
step "Subdominio: ssh. Dominio: $QUITSIE_DOMAIN. Servicio: SSH. URL: localhost:22."
pause "Cuando la ruta esté guardada, pulsa Enter"
check=$(curl -s -o /dev/null -m 15 -w '%{http_code} %{redirect_url}' "https://ssh.$QUITSIE_DOMAIN" 2>/dev/null || true)
case "$check" in
  *cloudflareaccess.com*) say "Correcto: ssh.$QUITSIE_DOMAIN exige pasar por Cloudflare Access." ;;
  *)
    warn "ssh.$QUITSIE_DOMAIN respondió «${check:-nada}», y no veo la redirección a Cloudflare Access."
    warn "Hasta que lo verifiques, borra la ruta ssh del túnel: no debe quedar sin protección."
    pause "Pulsa Enter para seguir de todos modos"
    ;;
esac

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Primer despliegue"
say "Configuro las variables de GitHub y lanzo el workflow Deploy sobre el último CI en verde de main."
note "La variable DEPLOY_SSH_HOST es el interruptor: con ella, cada push a main que pase la CI se despliega solo."
if ! gh workflow view deploy.yml >/dev/null 2>&1; then
  warn "GitHub aún no conoce .github/workflows/deploy.yml: integra la rama en main, haz push y repite esta etapa."
  SKIPPED+=("Primer despliegue: falta deploy.yml en main (después: gh workflow run deploy.yml --ref main)")
elif [[ -z "$(_existing DEPLOY_SSH_HOST_KEY || true)" ]]; then
  warn "Falta la clave pública de la VM (etapa 9). Repite esa etapa."
  SKIPPED+=("Primer despliegue: falta DEPLOY_SSH_HOST_KEY")
elif confirm "¿Activar el despliegue automático y lanzar el primero ahora?"; then
  set_var DEPLOY_SSH_HOST_KEY "$(_existing DEPLOY_SSH_HOST_KEY)"
  set_var QUITSIE_URL "https://$QUITSIE_DOMAIN"
  set_var DEPLOY_SSH_HOST "ssh.$QUITSIE_DOMAIN"
  if run gh workflow run deploy.yml --ref main; then
    sleep 8
    run_id=$(gh run list --workflow deploy.yml --limit 1 --json databaseId --jq '.[0].databaseId' 2>/dev/null || true)
    if [[ -n "$run_id" ]]; then
      gh run watch "$run_id" --exit-status || warn "El despliegue falló: mira el log con 'gh run view $run_id --log-failed'."
    fi
  fi
  say "Salud pública: $(curl -s -m 15 "https://$QUITSIE_DOMAIN/api/v1/health" || echo 'sin respuesta')"
  open_url "https://$QUITSIE_DOMAIN"
fi
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Prueba de restauración del respaldo"
say "Restauro el último respaldo de R2 en una carpeta temporal de la VM y compruebo su integridad."
say "La base real no se toca. Hazlo ahora y repítelo cada mes (docs/despliegue.md)."
note "Litestream sube los cambios casi al instante, pero la base no existe hasta el primer arranque del binario."
if confirm "¿Ejecutar quitsie-restore-test en la VM?"; then
  sleep 5
  run vm_ssh --command 'sudo systemctl is-active litestream && sudo quitsie-restore-test' </dev/null \
    || SKIPPED+=("Prueba de restauración: sudo quitsie-restore-test en la VM (docs/despliegue.md)")
fi
# ──────────────────────────────────────────────────────────────────────────

finish
say "Pendiente (no urgente):"
note "- quitsie.app: haz que redirija a $QUITSIE_DOMAIN con una Redirect Rule (docs/despliegue.md)."
note "- Apunta en tu calendario la caducidad del token de servicio y la prueba de restauración mensual."
note "- Acceso de emergencia a la VM: gcloud compute ssh $VM_NAME --zone $GCP_ZONE --tunnel-through-iap"
printf '\n'
